```python
import numpy as np

# Define the microphone array and sample rate
microphones = [0, 1, 2, 3, 4, 5, 6]
sample_rate = 44100

# Define the sound speed and wavelength of the ultrasonic emitter
sound_speed = 343  # meters per second
wavelength = 2 / sound_speed  # meters

# Define the position of the emitter
emitter_position = [0, 0, 0]  # meters

# Define the time difference between each microphone
time_differences = []
for i in range(len(microphones)):
    time_differences.append(np.abs(microphones[i] - emitter_position[0]) / sound_speed)

# Define the phase differences between each microphone
phase_differences = []
for i in range(len(microphones)):
    phase_differences.append(2 * np.pi * time_differences[i] * sample_rate / 1000)

# Calculate the position of the emitter using the least squares method
emitter_position_est = np.mean(phase_differences, axis=0)
emitter_position_est = emitter_position_est / (2 * np.pi * sound_speed)

# Print the estimated position of the emitter
print(emitter_position_est)
```
